const nav=document.querySelector('.header nav'),menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const o=nav.classList.toggle('open');menu.setAttribute('aria-expanded',o);menu.textContent=o?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';nav.querySelectorAll('a').forEach(x=>x.classList.toggle('active',x===a))}));
const info=document.querySelector('#info'),contact=document.querySelector('#contact-dialog');const practices=[['Консультации','Пространство для внимательного разговора о твоём запросе Можно начать с того, что сейчас занимает мысли: выбор, перемены, отношения с собой','Формат, длительность и условия встречи в этой презентации не назначены'],['Энергетические практики','Мягкое исследование своего состояния через внимание к телу, ощущениям и личному ритму','Эта концепция не обещает лечебного эффекта и не заменяет медицинскую помощь'],['Курсы и программы','Последовательный путь от первого знакомства с темой к собственной регулярной практике','Программа, даты и стоимость будут определены отдельно Сейчас можно обозначить свой интерес'],['Медитации','Небольшая пауза среди повседневных дел: замечать дыхание, звуки и ощущения, не требуя от себя результата','Начни с минуты тишины в удобном положении Остановись, если тебе некомфортно'],['Астрология и Таро','Символический язык для вопросов, образов и личного размышления','Это не достоверный способ предсказания событий и не основа для медицинских, финансовых или юридических решений']];
function openInfo(title,paras){document.querySelector('#info-title').textContent=title;const box=document.querySelector('#info-text');box.replaceChildren(...paras.map(t=>{const p=document.createElement('p');p.textContent=t;return p}));info.showModal()}document.querySelectorAll('[data-practice]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.practice);openInfo(practices[i][0],practices[i].slice(1))}));document.querySelector('#story-open').addEventListener('click',()=>openInfo('Быть ближе к себе',['Эта страница - визуальная концепция личного пространства Любови Безус','В окончательной версии здесь будет её собственная история: опыт, ценности и подход к работе Биографию и профессиональные квалификации важно рассказать её словами']));document.querySelector('#info-action').addEventListener('click',()=>{info.close();contact.showModal()});document.querySelectorAll('.start').forEach(b=>b.addEventListener('click',()=>contact.showModal()));
const thoughts=['Сегодня можно начать с простого: заметить, что ты чувствуешь прямо сейчас','Отдых не нужно заслуживать Иногда самый бережный шаг - сделать паузу','Оставь место любопытству: что нового ты можешь узнать о себе?','Попробуй сказать себе то, что сказала бы близкому человеку','Выбери одну небольшую идею, которую можешь воплотить сегодня'];document.querySelectorAll('[data-element]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-element]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelector('.element-thought').textContent=thoughts[Number(b.dataset.element)]}));const stories=document.querySelector('.story-cards');document.querySelector('#next').addEventListener('click',()=>stories.append(stories.firstElementChild));document.querySelector('#prev').addEventListener('click',()=>stories.prepend(stories.lastElementChild));
const breath=document.querySelector('#breathing');let timer=null;function resetBreath(){clearInterval(timer);timer=null;document.querySelector('.breath-orbit').classList.remove('running');document.querySelector('#breath-start').textContent='Начать';document.querySelector('#breath-time').textContent='60 секунд тишины'}document.querySelector('#breathe-open').addEventListener('click',()=>{resetBreath();breath.showModal()});document.querySelector('#breath-start').addEventListener('click',()=>{if(timer){resetBreath();return}let remaining=60;document.querySelector('.breath-orbit').classList.add('running');document.querySelector('#breath-start').textContent='Завершить';timer=setInterval(()=>{remaining--;document.querySelector('#breath-time').textContent=remaining+' секунд тишины';if(remaining<=0){resetBreath();document.querySelector('#breath-time').textContent='Спасибо за эту минуту для себя'}},1000)});breath.addEventListener('close',resetBreath);document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
